{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C03", "C08", "C12", "C17", "C21", "C32", "C35", "C36", "C38", "C42", "C43", "C44", "C58"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C03", "C12", "C17", "C32", "C21", "C08", "C58"],
  "claims": [
    {
      "claim": "The query is an SGLT2 inhibitor with a bridged dioxabicyclooctane core and the same 4-chloro-3-(4-ethoxybenzyl)phenyl aglycone as dapagliflozin; the closely related tofogliflozin context reports absolute oral bioavailability of about 97.5–98% in humans, 97% in a summary table, and 85% in monkeys, all far above the 20% threshold.",
      "card_ids": ["C03", "C12", "C17", "C32", "C21"]
    },
    {
      "claim": "A tofogliflozin record reports high bioavailability after a single 20 mg oral dose, consistent with the absolute bioavailability measurements.",
      "card_ids": ["C08"]
    },
    {
      "claim": "L3 dapagliflozin exposure records sharing the query aglycone show rapid absorption (median Tmax 0.75 h; Tmax ≤1.5 h) and comparable AUC between fed and fasted states and in mild hepatic impairment, supporting good oral absorption and exposure.",
      "card_ids": ["C35", "C36", "C38", "C42", "C43", "C44"]
    },
    {
      "claim": "L4 record C58 for dapagliflozin oral solution shows rapid absorption (Tmax <1 h) and at least 75% systemic absorption of the orally administered dose within 24 h based on urinary recovery of total radioactivity, supporting the absorption component for the shared aglycone.",
      "card_ids": ["C58"]
    },
    {
      "claim": "The remaining L4 records concern unrelated molecules (itraconazole, mosapride, atenolol, pioglitazone, ketoconazole) and provide no affirmative evidence relevant to the query's oral bioavailability.",
      "card_ids": ["C47", "C48", "C49", "C50", "C51", "C52", "C53", "C54", "C55", "C56", "C57"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C58"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is present; the decision relies on structural transfer from tofogliflozin and class/aglycone exposure data.",
    "No query-specific solubility or permeability assay is supplied in L4; the relevant L4 record is a dapagliflozin fraction-absorbed measurement from an oral solution, not an absolute F value.",
    "The tofogliflozin absolute-F records do not explicitly report a fasted condition; fasted-state transfer is inferred, though dapagliflozin L3 records show comparable AUC in fed vs fasted states.",
    "C58 reports systemic absorption of at least 75% for dapagliflozin, not the query itself, and does not directly measure absolute oral bioavailability.",
    "The query physicochemical prior is mixed (high TPSA/HBD), but no affirmative experimental evidence indicates F <20%."
  ],
  "decision_summary": "High: tofogliflozin absolute F ~97.5–98% in humans and dapagliflozin same-aglycone absorption ≥75% support F >=20%; L4 adds supportive absorption evidence and no affirmative low-F evidence is present."
}

